import{_ as t,o,c as a,a0 as i}from"./chunks/framework.CKZJaUMN.js";const m=JSON.parse('{"title":"Entities, ops, snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/model.md","filePath":"explanation/model.md"}'),n={name:"explanation/model.md"};function s(d,e,r,c,p,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="entities-ops-snapshots" tabindex="-1">Entities, ops, snapshots <a class="header-anchor" href="#entities-ops-snapshots" aria-label="Permalink to &quot;Entities, ops, snapshots&quot;">​</a></h1><p>The whole substrate is three primitives. Get these and the rest is plumbing.</p><h2 id="entity" tabindex="-1">Entity <a class="header-anchor" href="#entity" aria-label="Permalink to &quot;Entity&quot;">​</a></h2><p><code>{id, kind, node, indexDoc, health}</code></p><ul><li><code>kind</code> — free-form tag; the integration&#39;s namespace (<code>sepia-session</code>, <code>campaign</code>, …).</li><li><code>indexDoc</code> — opaque JSON for list views. Hypha merges and columnizes it; meaning belongs to the integration.</li><li><code>health</code> — liveness/lock state reported by the owner node.</li></ul><h2 id="op" tabindex="-1">Op <a class="header-anchor" href="#op" aria-label="Permalink to &quot;Op&quot;">​</a></h2><p><code>{entity, kind, payload}</code> — submitted to an entity&#39;s <strong>owner node</strong>.</p><ul><li><code>kind</code> is namespaced <code>&lt;integration&gt;.&lt;verb&gt;</code> (<code>sepia.prompt</code>, <code>campaign.start</code>); <code>entity.*</code> is the reserved substrate namespace (<code>entity.delete</code> only, today).</li><li><code>payload</code> is opaque to hypha — the owning plane interprets it.</li><li>Ops are idempotent-keyed and TTL&#39;d in the outbox; <code>Turn</code>-class ops dead-letter on first failure.</li></ul><h2 id="snapshot" tabindex="-1">Snapshot <a class="header-anchor" href="#snapshot" aria-label="Permalink to &quot;Snapshot&quot;">​</a></h2><p><code>{entity, ref, bytes}</code> — the migration primitive.</p><p>Serialize on the owner (<code>GET /api/entities/{id}/snapshot</code>), import on the target (<code>POST /api/entities/snapshot</code>). Bytes are opaque end-to-end; resume semantics are the integration&#39;s (<code>campaign-snapshot/v1</code>, sepia session IR export, …).</p><h2 id="why-generic" tabindex="-1">Why generic <a class="header-anchor" href="#why-generic" aria-label="Permalink to &quot;Why generic&quot;">​</a></h2><p>The distributed abilities — sync, arbitration, outbox, transfer, pairing — are orchestration-domain but workload-agnostic. Shaping them around sessions was the mistake ADR-0091 corrected; shaping them around <em>entities</em> is what lets bupha jobs, sturn claims, or cicada schedules become kinds without touching this repo.</p>',13)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
